import React, { useState, useEffect } from "react";
import { makeStyles } from "@material-ui/core/styles";
import { CryptoState } from "../CryptoContext";
import { Container, Typography, TextField, TableContainer, Table, TableHead, TableRow, TableCell, TableBody, Paper, LinearProgress, createTheme, ThemeProvider, Button, Box } from "@material-ui/core";
import { useHistory } from "react-router-dom";
import { useTheme } from "../ThemeContext";

export function numberWithCommas(x) {
  return x.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

const useStyles = makeStyles((theme) => ({
  container: {
    paddingTop: theme.spacing(4),
    paddingBottom: theme.spacing(4),
  },
  header: {
    fontWeight: 800,
    marginBottom: theme.spacing(4),
  },
  textField: {
    "& .MuiOutlinedInput-root": {
      borderRadius: 12,
      fontFamily: "'Inter', sans-serif",
      backgroundColor: "rgba(0,0,0,0.2)",
      "& fieldset": { borderColor: "rgba(255, 255, 255, 0.2)" },
      "&:hover fieldset": { borderColor: "rgba(255, 215, 0, 0.5)" },
      "&.Mui-focused fieldset": { borderColor: "#FFD700", borderWidth: 2 },
    },
    "& .MuiInputBase-input": { color: "#fff" },
    "& .MuiInputLabel-root": { color: "rgba(255,255,255,0.7)" },
  },
  textFieldLight: {
    "& .MuiOutlinedInput-root": {
      borderRadius: 12,
      fontFamily: "'Inter', sans-serif",
      backgroundColor: "rgba(255,255,255,0.5)",
      "& fieldset": { borderColor: "rgba(0, 0, 0, 0.2)" },
      "&:hover fieldset": { borderColor: "rgba(212, 175, 55, 0.5)" },
      "&.Mui-focused fieldset": { borderColor: "#d4af37", borderWidth: 2 },
    },
    "& .MuiInputBase-input": { color: "#111" },
    "& .MuiInputLabel-root": { color: "rgba(0,0,0,0.6)" },
  },
  tableContainer: {
    backdropFilter: "blur(12px)",
    backgroundColor: "rgba(20, 22, 26, 0.65)",
    border: "1px solid rgba(255, 255, 255, 0.05)",
    borderRadius: 16,
    boxShadow: "0 8px 32px 0 rgba(0, 0, 0, 0.3)",
    overflow: "hidden",
  },
  tableContainerLight: {
    backdropFilter: "blur(12px)",
    backgroundColor: "rgba(255, 255, 255, 0.75)",
    border: "1px solid rgba(0, 0, 0, 0.05)",
    borderRadius: 16,
    boxShadow: "0 8px 32px 0 rgba(31, 38, 135, 0.07)",
    overflow: "hidden",
  },
  tableHead: {
    background: "linear-gradient(45deg, #FFD700 30%, #FFA500 90%)",
  },
  tableHeadLight: {
    background: "linear-gradient(45deg, #d4af37 30%, #b8860b 90%)",
  },
  row: {
    cursor: "pointer",
    transition: "all 0.2s ease-in-out",
    "&:hover": {
      backgroundColor: "rgba(255, 215, 0, 0.08)",
      transform: "scale(1.01)",
    },
  },
  rowLight: {
    cursor: "pointer",
    transition: "all 0.2s ease-in-out",
    "&:hover": {
      backgroundColor: "rgba(212, 175, 55, 0.08)",
      transform: "scale(1.01)",
    },
  },
  paginationButton: {
    borderRadius: 8,
    border: "1px solid rgba(255, 215, 0, 0.5)",
    color: "#FFD700",
    fontWeight: 600,
    transition: "all 0.3s ease",
    "&:hover": {
      background: "rgba(255, 215, 0, 0.15)",
      boxShadow: "0 0 10px rgba(255, 215, 0, 0.4)",
    },
    "&:disabled": {
      borderColor: "rgba(255, 255, 255, 0.1)",
      color: "rgba(255, 255, 255, 0.3)",
    }
  },
  paginationButtonLight: {
    borderRadius: 8,
    border: "1px solid rgba(212, 175, 55, 0.5)",
    color: "#d4af37",
    fontWeight: 600,
    transition: "all 0.3s ease",
    "&:hover": {
      background: "rgba(212, 175, 55, 0.1)",
      boxShadow: "0 0 10px rgba(212, 175, 55, 0.2)",
    },
    "&:disabled": {
      borderColor: "rgba(0, 0, 0, 0.1)",
      color: "rgba(0, 0, 0, 0.3)",
    }
  },
  paginationButtonActive: {
    borderRadius: 8,
    background: "linear-gradient(45deg, #FFD700 30%, #FFA500 90%)",
    color: "#111",
    fontWeight: 800,
    boxShadow: "0 4px 10px rgba(255, 215, 0, 0.3)",
  },
  paginationButtonActiveLight: {
    borderRadius: 8,
    background: "linear-gradient(45deg, #d4af37 30%, #b8860b 90%)",
    color: "#fff",
    fontWeight: 800,
    boxShadow: "0 4px 10px rgba(212, 175, 55, 0.3)",
  },
}));

const CoinsTable = () => {
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);
  const { isDarkMode } = useTheme();

  // Get the context data and fetch function
  const { symbol, coins, loading, fetchCoins } = CryptoState();

  useEffect(() => {
    fetchCoins();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const classes = useStyles();
  const history = useHistory();

  const handleSearch = () => {
    return coins.filter(
      (coin) =>
        coin.name.toLowerCase().includes(search.toLowerCase()) ||
        coin.symbol.toLowerCase().includes(search.toLowerCase())
    );
  };

  const filteredCoins = handleSearch();
  const totalPages = Math.max(1, Math.ceil(filteredCoins.length / 10));

  useEffect(() => {
    if (page > totalPages) {
      setPage(totalPages);
    }
  }, [page, totalPages]);

  return (
    <Container className={classes.container}>
      <Typography
        variant="h4"
        className={classes.header}
        style={{
          color: isDarkMode ? "white" : "#111",
          textAlign: "center",
        }}
      >
        Cryptocurrency Prices by Market Cap
      </Typography>

      <TextField
        label="Search For a Crypto Currency.."
        variant="outlined"
        style={{ marginBottom: 30, width: "100%" }}
        className={isDarkMode ? classes.textField : classes.textFieldLight}
        onChange={(e) => setSearch(e.target.value)}
      />

      <TableContainer component={Paper} className={isDarkMode ? classes.tableContainer : classes.tableContainerLight} elevation={0}>
        {loading && <LinearProgress style={{ backgroundColor: "gold" }} />}

        <Table>
          <TableHead className={isDarkMode ? classes.tableHead : classes.tableHeadLight}>
            <TableRow>
              {["Coin", "Price", "24h Change", "Market Cap"].map((head) => (
                <TableCell
                  style={{
                    color: isDarkMode ? "#111" : "#fff",
                    fontWeight: "800",
                    fontSize: "1rem"
                  }}
                  key={head}
                  align={head === "Coin" ? "left" : "right"}
                >
                  {head}
                </TableCell>
              ))}
            </TableRow>
          </TableHead>

          <TableBody>
            {filteredCoins
              .slice((page - 1) * 10, (page - 1) * 10 + 10)
              .map((coin) => {
                  const profit = coin.price_change_percentage_24h > 0;

                  return (
                    <TableRow
                      onClick={() => history.push(`/coins/${coin.id}`)}
                      className={isDarkMode ? classes.row : classes.rowLight}
                      key={coin.name}
                    >
                      <TableCell
                        component="th"
                        scope="row"
                        style={{
                          display: "flex",
                          gap: 15,
                          borderBottom: isDarkMode ? "1px solid rgba(255,255,255,0.05)" : "1px solid rgba(0,0,0,0.05)"
                        }}
                      >
                        <img
                          src={coin?.image}
                          alt={coin.name}
                          height="50"
                          style={{ marginBottom: 10 }}
                        />
                        <div style={{ display: "flex", flexDirection: "column" }}>
                          <span style={{ textTransform: "uppercase", fontSize: 22, fontWeight: 700, color: isDarkMode ? "white" : "#111" }}>
                            {coin.symbol}
                          </span>
                          <span style={{ color: isDarkMode ? "#aaa" : "#666", fontWeight: 500 }}>
                            {coin.name}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell align="right" style={{ color: isDarkMode ? "white" : "#111", fontWeight: 600, borderBottom: isDarkMode ? "1px solid rgba(255,255,255,0.05)" : "1px solid rgba(0,0,0,0.05)" }}>
                        {symbol}{" "}
                        {numberWithCommas((coin.current_price || 0).toFixed(2))}
                      </TableCell>
                      <TableCell
                        align="right"
                        style={{
                          color: profit > 0 ? "rgb(14, 203, 129)" : "#ff4d4d",
                          fontWeight: 700,
                          borderBottom: isDarkMode ? "1px solid rgba(255,255,255,0.05)" : "1px solid rgba(0,0,0,0.05)"
                        }}
                      >
                        {profit && "+"}
                        {coin.price_change_percentage_24h ? coin.price_change_percentage_24h.toFixed(2) : "0.00"}%
                      </TableCell>
                      <TableCell align="right" style={{ color: isDarkMode ? "white" : "#111", fontWeight: 600, borderBottom: isDarkMode ? "1px solid rgba(255,255,255,0.05)" : "1px solid rgba(0,0,0,0.05)" }}>
                        {symbol}{" "}
                        {numberWithCommas((coin.market_cap || 0).toString().slice(0, -6))} M
                      </TableCell>
                    </TableRow>
                  );
              })}
            {!loading && filteredCoins.length === 0 && (
              <TableRow>
                <TableCell colSpan={4} align="center" style={{ padding: 32, color: isDarkMode ? "#aaa" : "#555" }}>
                  No coins match your search.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </TableContainer>

      <Box
        style={{
          padding: "30px 0",
          width: "100%",
          display: "flex",
          justifyContent: "center",
          gap: 12,
        }}
      >
        <Button
          variant="outlined"
          disabled={page === 1}
          onClick={() => {
            setPage((prev) => Math.max(1, prev - 1));
            window.scroll(0, 450);
          }}
          className={isDarkMode ? classes.paginationButton : classes.paginationButtonLight}
        >
          Prev
        </Button>
        {Array.from({ length: Math.min(totalPages, 5) }, (_, idx) => idx + 1).map((p) => {
          let rootClass = isDarkMode ? classes.paginationButton : classes.paginationButtonLight;
          if (page === p) {
            rootClass = isDarkMode ? classes.paginationButtonActive : classes.paginationButtonActiveLight;
          }
          return (
            <Button
              key={p}
              onClick={() => {
                setPage(p);
                window.scroll(0, 450);
              }}
              className={rootClass}
            >
              {p}
            </Button>
          )
        })}
        <Button
          variant="outlined"
          disabled={page === totalPages}
          onClick={() => {
            setPage((prev) => Math.min(totalPages, prev + 1));
            window.scroll(0, 450);
          }}
          className={isDarkMode ? classes.paginationButton : classes.paginationButtonLight}
        >
          Next
        </Button>
      </Box>
    </Container>
  );
};

export default CoinsTable;
